CREATE TEMP TABLE _cu(sku text, alan text, eski text, yeni text, yol text) ON COMMIT DROP;
INSERT INTO _cu
SELECT u.sku, 'unitCostUsd', p."unitCostUsd"::text, u.usd::text, u.yol FROM _uc u JOIN public."Product" p ON p.sku = u.sku
 WHERE round(p."unitCostUsd", 4) IS NOT DISTINCT FROM u.usd_eski AND round(p."unitCostTry", 2) IS NOT DISTINCT FROM u.try_eski AND p."unitCostUsd" IS DISTINCT FROM u.usd
UNION ALL
SELECT u.sku, 'unitCostTry', p."unitCostTry"::text, u.try::text, u.yol FROM _uc u JOIN public."Product" p ON p.sku = u.sku
 WHERE round(p."unitCostUsd", 4) IS NOT DISTINCT FROM u.usd_eski AND round(p."unitCostTry", 2) IS NOT DISTINCT FROM u.try_eski AND p."unitCostTry" IS DISTINCT FROM u.try;
UPDATE public."Product" p SET "unitCostUsd" = u.usd, "unitCostTry" = u.try, "updatedAt" = now()
  FROM _uc u WHERE u.sku = p.sku AND EXISTS (SELECT 1 FROM _cu WHERE _cu.sku = p.sku);
INSERT INTO public.cfo_change_log (id, area, item, "oldValue", "newValue", source, kind, note)
SELECT gen_random_uuid()::text, 'maliyet', sku || ' ' || alan, eski, yeni, 'Alperen (tam yetki) + Claude Code', 'duzeltme',
       'İthalat motoru maliyeti (calcImportCost): RMB/6,8 × 1,05 + ' || yol || ' navlun + GTİP gümrüğü (KDV/ÖTV dahil); USD/TRY cfo_kur 2026-10 = 48,98. Kaynak: maliyet Excel''i, docs/maliyet/2026-10-10-maliyet-excel-eslestirme.md' FROM _cu;
COMMIT;
